def maximum_equal_length_runs(s):
    from collections import Counter
    lengths=Counter();start=0
    for i in range(1,len(s)+1):
        if i==len(s) or s[i]!=s[start]:lengths[i-start]+=1;start=i
    return max(lengths.values())

